package com.example.bluehive.homeScreenSectionRules

import com.example.bluehive.testutil.MainSource
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/**
 * The Latest Trailers panel's metal TV (v557; level-1 tones since v559; corner light since v560, softened in v562; top-left darkened in v564): the frame and its focus glow
 * are generated by tools/home-art/make_trailer_frame.py to fit the viewport,
 * and the panel draws them at exactly their size (2 px per dp, xhdpi).
 */
class TrailerFrameArtTest {

    private val code = MainSource.code("latestTrailersComponents/HomeScreenTrailerSectionCompose.kt")
    private val res = listOf(File("src/main/res"), File("app/src/main/res")).first { it.isDirectory }

    /** Width and height of a lossless (VP8L) WebP, from its header. */
    private fun webpSize(f: File): Pair<Int, Int> {
        val b = f.readBytes()
        assertEquals("VP8L", String(b, 12, 4, Charsets.US_ASCII))
        val bits = (b[21].toInt() and 0xFF) or ((b[22].toInt() and 0xFF) shl 8) or
            ((b[23].toInt() and 0xFF) shl 16) or ((b[24].toInt() and 0xFF) shl 24)
        return ((bits and 0x3FFF) + 1) to (((bits shr 14) and 0x3FFF) + 1)
    }

    private fun spec(name: String): Double =
        Regex("""val $name = ([0-9.]+)\.dp""").find(code)!!.groupValues[1].toDouble()

    @Test
    fun `the frame and the glow are drawn at exactly their pixel size`() {
        val (fw, fh) = webpSize(File(res, "drawable-xhdpi/trailer_frame.webp"))
        val (gw, gh) = webpSize(File(res, "drawable-xhdpi/new_trailer_frame_focused.webp"))
        assertEquals(fw / 2.0, spec("frameW"), 0.01)
        assertEquals(fh / 2.0, spec("frameH"), 0.01)
        assertEquals(gw / 2.0, spec("focusedW"), 0.01)
        assertEquals(gh / 2.0, spec("focusedH"), 0.01)
    }

    @Test
    fun `the picture sits in the panel, the glow centred on the frame`() {
        // 11 dp of rim + 4 dp of panel above and left of the picture.
        assertEquals(spec("viewportX") - 15, spec("frameX"), 0.01)
        assertEquals(spec("viewportY") - 15, spec("frameY"), 0.01)
        val margin = spec("frameX") - spec("focusedX")
        assertEquals(margin, spec("frameY") - spec("focusedY"), 0.01)
        assertEquals(spec("focusedW"), spec("frameW") + 2 * margin, 0.01)
        assertEquals(spec("focusedH"), spec("frameH") + 2 * margin, 0.01)
    }

    @Test
    fun `the generator is in the repo`() {
        val root = listOf(File("."), File("..")).first { File(it, "tools/home-art").isDirectory }
        val script = File(root, "tools/home-art/make_trailer_frame.py").readText()
        assertTrue(script.contains("RIM_TOP, RIM_BOTTOM = (0x2C, 0x2D, 0x32), (0x1A, 0x1B, 0x1E)"))
        assertTrue(script.contains("PANEL_TOP, PANEL_BOTTOM = (0x1A, 0x1A, 0x1E), (0x0B, 0x0B, 0x0D)"))
        // The rim's light line sits on the top-right and bottom-left corners (v560).
        assertTrue(script.contains("strong = RIM_HIGHLIGHT * smoothstep(0.2, 0.85, abs(u))"))
        assertTrue(script.contains("u = x / w - y / h"))
        // A soft glare behind the line on those two corners; no lit edge on the top-left.
        assertTrue(script.contains("for cx, cy in ((w - c, c), (c, h - c)):"))
        assertTrue(script.contains("rim = lit(face, om, 4, 4.0, 0.0, 0.45)"))
        // The metal darkens toward the top-left only; the bottom-right keeps its tone (v564).
        assertTrue(script.contains("RIM_TL_DARKEN = 0.25 "))
        assertTrue(script.contains("* (1 - toward_br))"))
        // Soft glare and a hairline (v562): option E at 0.8 px.
        assertTrue(script.contains("GLARE = 0.06 "))
        assertTrue(script.contains("RIM_LINE_PX = 0.8 "))
    }
}
